using System;
using System.IO;
using System.Linq;
using System.Collections;
using NUnit.Framework;
using Unity.FPS.AI;
using Unity.FPS.Game;
using Unity.FPS.Gameplay;
using UnityEngine;
using UnityEngine.AI;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
using UnityEngine.SceneManagement;
using UnityEngine.TestTools;
using UnityEditor;
using UnityEditor.SceneManagement;
using Object=UnityEngine.Object;
namespace IronRequiem.Tests
{
 public sealed class SawBotTests
 {
  const string Prefab="Assets/IronRequiem/Prefabs/Enemies/SawBot_AI_v01.prefab",Lab="Assets/IronRequiem/Scenes/SawBotLab.unity",Reports="Tools/IronRequiem/Reports/SawBotGameplay";
  PlayerCharacterController player;Keyboard keys;Mouse mouse;float capture;bool background;UnityEngine.InputSystem.Utilities.ReadOnlyArray<InputDevice>? devices;SawBotCombat bot;EnemyController enemy;
  [UnitySetUp] public IEnumerator Setup(){capture=Time.captureDeltaTime;background=Application.runInBackground;Time.captureDeltaTime=1f/60;Application.runInBackground=true;Time.timeScale=1;devices=InputSystem.actions.devices;keys=InputSystem.AddDevice<Keyboard>();mouse=InputSystem.AddDevice<Mouse>();InputSystem.actions.devices=new InputDevice[]{keys,mouse};keys.MakeCurrent();mouse.MakeCurrent();EditorSceneManager.LoadSceneInPlayMode(Lab,new LoadSceneParameters(LoadSceneMode.Single));yield return null;yield return null;var menu=Object.FindAnyObjectByType<CombatLabMenu>();menu.BeginGame();menu.enabled=false;var waves=Object.FindAnyObjectByType<CombatTwoRoomsLab>();waves.enabled=false;var flow=Object.FindAnyObjectByType<GameFlowManager>();if(flow)flow.enabled=false;var objectives=Object.FindAnyObjectByType<ObjectiveManager>();if(objectives)objectives.enabled=false;if(waves.SpawnQueue)waves.SpawnQueue.enabled=false;player=Object.FindAnyObjectByType<PlayerCharacterController>();player.enabled=false;player.GetComponent<Health>().Invincible=true;foreach(var c in Object.FindObjectsByType<Collider>())if(!c.transform.IsChildOf(player.transform)&&!(c.bounds.size.y<2&&c.bounds.size.x>20&&c.bounds.size.z>20))c.enabled=false;Move(new Vector3(-12,.03f,-10));Cursor.lockState=CursorLockMode.Locked;yield return null;}
  [UnityTearDown]public IEnumerator Cleanup(){Time.timeScale=1;Time.captureDeltaTime=capture;AudioListener.pause=false;InputSystem.actions.devices=devices;InputSystem.RemoveDevice(keys);InputSystem.RemoveDevice(mouse);Cursor.lockState=CursorLockMode.None;var scene=SceneManager.GetActiveScene();SceneManager.SetActiveScene(SceneManager.CreateScene("SawCleanup"+Time.frameCount));yield return SceneManager.UnloadSceneAsync(scene);Application.runInBackground=background;}
  void Move(Vector3 p){var c=player.GetComponent<CharacterController>();c.enabled=false;player.transform.SetPositionAndRotation(p,Quaternion.identity);c.enabled=true;player.CharacterVelocity=Vector3.zero;Physics.SyncTransforms();}
  IEnumerator Spawn(Vector3 wanted){Assert.That(NavMesh.SamplePosition(wanted,out var point,4,NavMesh.AllAreas),Is.True,"Bunker navmesh exists");var go=Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(Prefab),point.position,Quaternion.Euler(0,180,0));bot=go.GetComponent<SawBotCombat>();enemy=go.GetComponent<EnemyController>();var route=new GameObject("SawPatrol").AddComponent<PatrolPath>();route.PathNodes.Add(player.transform);enemy.PatrolPath=route;yield return null;yield return null;}
  IEnumerator Until(Func<bool> condition,float seconds,string label){float end=Time.realtimeSinceStartup+seconds*3;while(!condition()&&Time.realtimeSinceStartup<end){Assert.That(Time.timeScale,Is.EqualTo(1),"Simulation paused while "+label);yield return null;}Assert.That(condition(),Is.True,label+" state="+(bot?bot.GetComponent<EnemyMobile>().AiState.ToString():"none"));}
  void Stop(){bot.GetComponent<EnemyMobile>().enabled=false;if(enemy.NavMeshAgent.isOnNavMesh)enemy.NavMeshAgent.isStopped=true;}
  [UnityTest]public IEnumerator SharedRigLodsAndAnimations()
  {
   yield return Spawn(new Vector3(-12,0,8));Stop();var skins=bot.GetComponentsInChildren<SkinnedMeshRenderer>(true);Assert.That(skins.Length,Is.EqualTo(3));Assert.That(bot.GetComponent<WeaponController>(),Is.Null);Assert.That(enemy.GetCurrentWeapon(),Is.Null);Assert.That(bot.Animator.applyRootMotion,Is.False);Assert.That(bot.Animator.runtimeAnimatorController.animationClips.Select(c=>c.name).Distinct().Count(),Is.EqualTo(5));
   foreach(var s in skins){Assert.That(s.bones.Length,Is.EqualTo(11));Assert.That(s.bones,Is.EqualTo(skins[0].bones));Assert.That(s.sharedMesh.subMeshCount,Is.EqualTo(1));Assert.That(s.sharedMaterial,Is.SameAs(skins[0].sharedMaterial));Assert.That(s.sharedMesh.boneWeights.All(w=>Mathf.Abs(w.weight0-1)<.001f&&w.boneIndex0<11),Is.True);}
   var arm=bot.GetComponentsInChildren<Transform>().Single(t=>t.name=="UpperArm_L");var rest=arm.localRotation;bot.Animator.SetFloat("AttackSpeed",1);bot.Animator.Play("Attack",0,0);yield return new WaitForSeconds(.5f);Assert.That(Quaternion.Angle(rest,arm.localRotation),Is.GreaterThan(35));Assert.That(bot.HitCount,Is.Zero,"Pose preview alone does not deal damage");foreach(var s in skins){var baked=new Mesh();s.BakeMesh(baked);Assert.That(baked.vertexCount,Is.GreaterThan(100));Assert.That(baked.vertices.All(v=>!float.IsNaN(v.x)&&!float.IsNaN(v.y)&&!float.IsNaN(v.z)),Is.True);Object.Destroy(baked);}File.WriteAllText(Reports+"/rig.txt","3 LODs share11 rigid bones, unit weights and one material. Five Animator clips. Attack bends real articulated arms across all LODs; no root motion or preview damage.");
  }
  [UnityTest]public IEnumerator PursuitTurningAndWheelTravel()
  {
   yield return Spawn(new Vector3(-12,0,10));Vector3 initial=bot.transform.position;var wheel=bot.LeftWheel.localRotation;yield return Until(()=>Vector3.Distance(initial,bot.transform.position)>3,5,"Actual EnemyMobile/NavMesh pursuit");Assert.That(Quaternion.Angle(wheel,bot.LeftWheel.localRotation),Is.GreaterThan(5));Assert.That(enemy.IsSeeingTarget,Is.True);Assert.That(Object.FindObjectsByType<ProjectileBase>().Length,Is.Zero);Move(new Vector3(-4,.03f,-4));yield return new WaitForSeconds(.5f);Assert.That(Vector3.Dot(bot.transform.forward,Vector3.ProjectOnPlane(player.transform.position-bot.transform.position,Vector3.up).normalized),Is.GreaterThan(.2f));File.WriteAllText(Reports+"/navigation.txt","Actual NavMesh/EnemyMobile pursuit moved >3m; differential wheels rotated from displacement; target relocation produced a turn. No gun or projectile.");
  }
  [UnityTest]public IEnumerator TelegraphSingleImpactAndDeathDuringAttack()
  {
   yield return Spawn(new Vector3(-12,0,-6));Move(bot.transform.position+Vector3.back*1.15f);var hp=player.GetComponent<Health>();hp.Invincible=false;hp.MaxHealth=hp.CurrentHealth=500;yield return Until(()=>bot.IsAttacking,4,"Windup begins");float before=hp.CurrentHealth;yield return new WaitForSeconds(.3f);Assert.That(hp.CurrentHealth,Is.EqualTo(before),"No windup damage");yield return Until(()=>hp.CurrentHealth<before,2,"Animation event damages player");Assert.That(before-hp.CurrentHealth,Is.EqualTo(bot.Damage).Within(.001));Assert.That(bot.HitCount,Is.EqualTo(1));bot.Impact();bot.Impact();Assert.That(hp.CurrentHealth,Is.EqualTo(before-bot.Damage));yield return Until(()=>bot.AttackCount>=2&&bot.IsAttacking,3,"Next attack");int count=bot.HitCount;bot.GetComponent<Health>().Kill();yield return new WaitForSeconds(.9f);Assert.That(bot.HitCount,Is.EqualTo(count));Assert.That(bot.IsDead,Is.True);Assert.That(enemy.NavMeshAgent.enabled,Is.False);Assert.That(bot.GetComponent<EnemyMobile>().enabled,Is.False);Assert.That(bot.DeathCount,Is.EqualTo(1));File.WriteAllText(Reports+"/melee.txt","Visible windup >.3s, real animation event damage12 once despite repeated impact calls. Subsequent attack interrupted by real Health death; no late damage, agent/AI stop.");
  }
  [UnityTest]public IEnumerator WallCancelsAndNavigationRecovers()
  {
   Move(new Vector3(-12,.03f,-5));var wall=GameObject.CreatePrimitive(PrimitiveType.Cube);wall.name="SawWall";wall.transform.position=new Vector3(-12,2,-2);wall.transform.localScale=new Vector3(6,5,.6f);var obstacle=wall.AddComponent<NavMeshObstacle>();obstacle.carving=true;obstacle.shape=NavMeshObstacleShape.Box;obstacle.size=Vector3.one;yield return null;yield return Spawn(new Vector3(-12,0,2));yield return new WaitForSeconds(.15f);Assert.That(bot.HitCount,Is.Zero);Assert.That(bot.CanAttack,Is.False);float end=Time.time+8;bool detour=false;while(Time.time<end&&bot.AttackCount==0){if(enemy.NavMeshAgent.hasPath&&enemy.NavMeshAgent.path.corners.Length>2)detour=true;yield return null;}Assert.That(detour,Is.True,"NavMesh detour around obstacle");Assert.That(bot.AttackCount,Is.GreaterThan(0));Stop();var blocker=GameObject.CreatePrimitive(PrimitiveType.Cube);blocker.transform.position=(bot.transform.position+player.transform.position)*.5f+Vector3.up;blocker.transform.localScale=new Vector3(8,4,.3f);Physics.SyncTransforms();int hits=bot.HitCount;yield return new WaitForSeconds(1);Assert.That(bot.IsAttacking,Is.False);Assert.That(bot.HitCount,Is.EqualTo(hits));File.WriteAllText(Reports+"/obstacles.txt","Carving obstacle forces a real detour and target reacquisition. Solid wall inserted during windup cancels attack; no through-wall damage.");
  }
  [UnityTest]public IEnumerator PlayerBulletsMeleeFeedbackAndCorpse()
  {
   File.WriteAllText(Reports+"/damage-stage.txt","spawn");yield return Spawn(new Vector3(-12,0,-5));File.AppendAllText(Reports+"/damage-stage.txt"," stop");Stop();bot.enabled=false;enemy.enabled=false;Move(bot.transform.position+Vector3.back*3);player.PlayerCamera.transform.LookAt(bot.GetComponent<Actor>().AimPoint.position);yield return new WaitForSeconds(1);var hp=bot.GetComponent<Health>();File.AppendAllText(Reports+"/damage-stage.txt"," shoot");float before=hp.CurrentHealth;var weapon=player.GetComponent<PlayerWeaponsManager>().GetActiveWeapon();Assert.That(weapon.HandleShootInputs(true,true,false),Is.True);yield return Until(()=>hp.CurrentHealth<before,2,"Real player projectile hits SawBot");File.AppendAllText(Reports+"/damage-stage.txt"," projectile hit");var feedback=bot.GetComponent<RobotHitFeedback>();Assert.That(feedback.FlashCount,Is.GreaterThan(0));yield return new WaitForSeconds(.35f);Assert.That(feedback.IsFlashing,Is.False);Move(bot.transform.position+Vector3.back*1.0f);player.PlayerCamera.transform.LookAt(bot.GetComponent<Actor>().AimPoint.position);Physics.SyncTransforms();File.AppendAllText(Reports+"/damage-stage.txt"," punch");before=hp.CurrentHealth;InputSystem.QueueStateEvent(keys,new KeyboardState(Key.F));yield return null;yield return null;InputSystem.QueueStateEvent(keys,new KeyboardState());yield return new WaitForSeconds(.7f);Assert.That(before-hp.CurrentHealth,Is.EqualTo(player.GetComponent<ProtagonistMelee>().Damage).Within(.001),"One punch per target across multiple hitboxes");File.AppendAllText(Reports+"/damage-stage.txt"," kill");int deaths=0;hp.OnDie+=()=>deaths++;hp.Kill();hp.Kill();yield return new WaitForSeconds(1.3f);File.AppendAllText(Reports+"/damage-stage.txt"," corpse");Assert.That(deaths,Is.EqualTo(1));Assert.That(bot.DeathCount,Is.EqualTo(1));Assert.That(bot.transform.position.y,Is.InRange(-.2f,.3f));foreach(var skin in bot.GetComponentsInChildren<SkinnedMeshRenderer>(true)){var baked=new Mesh();skin.BakeMesh(baked);float bottom=baked.vertices.Min(v=>skin.transform.TransformPoint(v).y);Assert.That(bottom,Is.GreaterThan(-.07f));Object.Destroy(baked);}yield return new WaitForSeconds(3);Assert.That(!bot,Is.True,"Existing EnemyController cleanup");File.WriteAllText(Reports+"/damage-death.txt","Real player projectile, white flash restoration, F punch single damage across hitboxes, massive/repeated death once, sampled death skin above ground and corpse cleanup. No collectible saw invented.");
  }
  [UnityTest]public IEnumerator BunkerWaveContainsOneSawBotAndTracksDeath()
  {
   EditorSceneManager.LoadSceneInPlayMode("Assets/IronRequiem/Scenes/BunkerLab.unity",new LoadSceneParameters(LoadSceneMode.Single));yield return null;yield return null;var menu=Object.FindAnyObjectByType<CombatLabMenu>();menu.BeginGame();menu.enabled=false;player=Object.FindAnyObjectByType<PlayerCharacterController>();player.GetComponent<Health>().Invincible=true;player.enabled=false;var waves=Object.FindAnyObjectByType<CombatTwoRoomsLab>();Move(new Vector3(0,.03f,-20));yield return Until(()=>waves.PendingSpawns==0&&waves.LivingEnemies==7,8,"First bunker wave:6 T07+1 SawBot");var saw=waves.Living.Select(h=>h.GetComponent<SawBotCombat>()).Where(b=>b).ToArray();Assert.That(saw.Length,Is.EqualTo(1));saw[0].GetComponent<Health>().Kill();yield return null;Assert.That(waves.LivingEnemies,Is.EqualTo(6));File.WriteAllText(Reports+"/bunker.txt","Bunker first wave contains original6 T07 plus1 SawBot, spawned through existing queue. Saw death removes exactly one live enemy; corpse is not counted.");
  }
 }
}